// 在实际Electron隔离renderer中运行；只用生产preload暴露的有限动作。
import {Page} from '../../../renderer/pages/provider-settings';
import {createModelCenterAdapters} from '../../../renderer/pages/model-center-adapter';
const g=globalThis as any;
const Vue=g.Vue;
(async()=>{
  const checks:string[]=[];
  const check=(ok:boolean,label:string)=>{if(!ok)throw new Error(label);checks.push(label);};
  const wait=()=>new Promise(resolve=>setTimeout(resolve,40));
  const until=async(fn:()=>boolean,label:string)=>{for(let i=0;i<100;i++){await wait();await Vue.nextTick();if(fn())return;}throw new Error(label);};
  const adapters=createModelCenterAdapters(g.sacode),adapter=adapters['provider-settings'];
  let ui:any;
  const mount=()=>{ui=Vue.createApp({render:()=>Vue.h(Page,{adapter})});ui.mount('#fixture');};
  const button=(label:string)=>Array.from(document.querySelectorAll('button')).find(n=>n.getAttribute('aria-label')===label) as HTMLButtonElement;
  const text=()=>document.querySelector('#fixture')!.textContent||'';
  const pullLabel='拉取 合成供应商 模型目录';
  mount();await until(()=>!!button(pullLabel)&&!button(pullLabel).disabled,'供应商未就绪');
  button(pullLabel).click();await until(()=>!!button('取消当前模型拉取'),'未显示取消');
  check(button(pullLabel).disabled,'在途不允许重复拉取');
  const first=adapter.pullSnapshot()!.operationId;
  check(text().includes(first),'发送前ID可见');
  button('取消当前模型拉取').click();
  await until(()=>text().includes('已取消'),'未获得Host取消回执');
  for(let i=0;i<30&&button(pullLabel).disabled;i++){button('查询当前模型拉取结果').click();await wait();}
  await until(()=>!button(pullLabel).disabled,'取消线程未收束');
  check(text().includes('后台已收束'),'取消及资源收束分别确认');
  const rows=await g.sacode.modelsDescribe();
  check(rows.providers[0].models.length===1,'取消不写入新模型');
  button(pullLabel).click();await until(()=>text().includes('已拉取成功'),'正常拉取未成功');
  check(adapter.pullSnapshot()!.operationId!==first,'新操作使用新ID');
  await until(()=>!button(pullLabel).disabled,'成功后未解锁');
  button(pullLabel).click();await wait();
  const third=adapter.pullSnapshot()!.operationId;
  ui.unmount();mount();await until(()=>text().includes(third),'页签重挂载丢失操作ID');
  await until(()=>text().includes('拉取结果未知'),'查询失败后未知提示未持续展示');
  check(button(pullLabel).disabled&&button(pullLabel).textContent==='结果待核对','未知时按钮不冒充仍在拉取且禁止重发');
  check(text().includes('刷新供应商目录只读取当前配置'),'区分目录刷新与原操作核对');
  await new Promise(resolve=>setTimeout(resolve,850));
  button('刷新供应商目录').click();await wait();
  check(text().includes('拉取结果未知')&&button(pullLabel).disabled,'真实目录已有新模型也不能替代原操作回执');
  button('查询当前模型拉取结果').click();
  await until(()=>text().includes('本次核对未取得有效回执'),'手动核对失败没有单独说明');
  check(text().includes('拉取结果未知')&&button(pullLabel).disabled,'核对失联继续保留未知和禁止重发');
  ui.unmount();mount();await until(()=>text().includes(third),'未知态重挂载丢失身份');
  check(text().includes('本次核对未取得有效回执'),'重挂载保留核对失败说明');
  button('查询当前模型拉取结果').click();
  await until(()=>text().includes('已拉取成功')&&!button(pullLabel).disabled,'精确查询未找回成功');
  check(adapter.pullSnapshot()!.operationId===third,'桥丢回执后按原ID查询，不重新拉取');
  check(!!document.querySelector('[aria-live="polite"]'),'状态变化可被辅助技术播报');
  ui.unmount();g.__pullResult={ok:true,checks};
})().catch((e:Error)=>{g.__pullResult={ok:false,error:e.message};});
